def canonical_5(nodes, adjset):
    idx = nodes
    edge_masks = []
    best = None
    for perm in itertools.permutations(range(5)):
        code = 0
        bit = 0
        for a in range(5):
            for b in range(a+1,5):
                u = idx[perm[a]]; v = idx[perm[b]]
                if (u,v) in adjset or (v,u) in adjset:
                    code |= 1 << bit
                bit += 1
        # prefer max because codes for complements are far away; any consistent extremum works
        if best is None or code > best:
            best = code
    return best

