    clusters = {frozenset([seed])}
    for size in range(2,6):
        nxt = set()
        for cl in clusters:
            frontier = set()
            for u in cl:
                frontier.update(adj[u])
            frontier.difference_update(cl)
            for v in frontier:
                nxt.add(cl | {v})
        clusters = nxt
    sets.update(clusters)
