iso = {}
examples = {}
for cl in sets:
    nodes = sorted(cl)
    adjset = set()
    for u in nodes:
        for v in adj[u]:
            if v in cl and u < v:
                adjset.add((u,v))
    cert = canonical_5(nodes, adjset)
    iso[cert] = iso.get(cert,0)+1
    examples.setdefault(cert, cl)

print('isomorphism classes:', len(iso))
for cert,count in sorted(iso.items(), key=lambda kv: kv[0]):
    cl = examples[cert]
    edges = [(u,v) for u in cl for v in adj[u] if v in cl and u<v]
    degrees = tuple(sorted(sum(1 for u,v in edges if u==s or v==s) for s in cl))
