from fractions import Fraction as F

# Kagome lattice: triangular Bravais lattice with primitive vectors
# a1=(1,0), a2=(1/2, sqrt(3)/2), and 3-site basis
# A=(0,0), B=(1/2,0), C=(1/4,sqrt(3)/4). NN distance 1/2.
# Site = (i,j,b) -> position i*a1 + j*a2 + basis[b]
# Nearest-neighbor offsets derived from geometry:
# A(i,j): B(i,j), B(i-1,j), C(i,j), C(i,j-1)
# B(i,j): A(i,j), A(i+1,j), C(i,j), C(i+1,j-1)
# C(i,j): A(i,j), A(i,j+1), B(i,j), B(i-1,j+1)
def neighbors(s):
    i,j,b=s
    if b==0:
        return [(i,j,1),(i-1,j,1),(i,j,2),(i,j-1,2)]
    if b==1:
        return [(i,j,0),(i+1,j,0),(i,j,2),(i+1,j-1,2)]
    return [(i,j,0),(i,j+1,0),(i,j,1),(i-1,j+1,1)]

# Verify geometry with exact squared distances using (x = i + j/2 + bx, y = sqrt3*(j/2+by))
def pos(s):
    i,j,b=s
    bx,by=[(F(0),F(0)),(F(1,2),F(0)),(F(1,4),F(1,4))][b]
    # store (x, y"'^2/3) pair: x exact, t=(y/sqrt3)
    return (i + j/F(2) + bx, j/F(2) + by)

