from fractions import Fraction as F

# Positions in lattice-coordinate exact form: x = i + j/2 + bx, t = y/sqrt3 = j/2 + by.
BASIS=[(F(0),F(0)),(F(1,2),F(0)),(F(1,4),F(1,4))]
def pos(s):
    i,j,b=s
    bx,bt=BASIS[b]
    return (i+j/F(2)+bx, j/F(2)+bt)

def neighbors(s):
    i,j,b=s
    if b==0: return [(i,j,1),(i-1,j,1),(i,j,2),(i,j-1,2)]
    if b==1: return [(i,j,0),(i+1,j,0),(i,j,2),(i+1,j-1,2)]
    return [(i,j,0),(i,j+1,0),(i,j,1),(i-1,j+1,1)]

R=6
sites=[(i,j,b) for i in range(-R,R+1) for j in range(-R,R+1) for b in range(3)]
sset=set(sites)
adj={s:[t for t in neighbors(s) if t in sset] for s in sites}
core={s for s in sites if max(abs(s[0]),abs(s[1]),abs(s[0]+s[1]))<=1}
raw=set()
for seed in core:
    cls={frozenset([seed])}
    for _ in range(2,6):
        nxt=set()
        for cl in cls:
            frontier=set()
            for u in cl: frontier.update(adj[u])
            frontier.difference_update(cl)
            for v in frontier: nxt.add(cl|{v})
        cls=nxt
    raw.update(cls)
print('raw connected 5-sets',len(raw))

# Generate the 12 triangular-lattice isometries in (x,t) Cartesian coordinates.
# These are rotations by k*pi/3, optionally followed by reflection in x-axis.
def mat_mul(A,B):
    return tuple(tuple(sum(A[i][k]*B[k][j] for k in range(2)) for j in range(2)) for i in range(2))
# integer square-root-free representation: each linear map on Q(x,t) basis
# rotation 60: (x,t)->(x/2 + 3t/2, -x/2 + t/2)? derive using exact coordinates.
# Use matrices in basis (1 in x, 1 in t): rotation theta: x'=c x + s sqrt3 t; t'= -s x/sqrt3 + c t.
# for theta=k*pi/3: entries halves.
def rot(k):
    vals=[(1,0,0,1),(F(1,2),F(3,2),F(-1,2),F(1,2)),(F(-1,2),F(3,2),F(-1,2),F(-1,2)),
          (-1,0,0,-1),(F(-1,2),F(-3,2),F(1,2),F(-1,2)),(F(1,2),F(-3,2),F(1,2),F(1,2))][k%6]
    return ((vals[0],vals[1]),(vals[2],vals[3]))
REFL=((F(1),F(0)),(F(0),F(-1)))
MATS=[]
for k in range(6):
    M=rot(k)
    MATS.append(M)
    MATS.append(mat_mul(M,REFL))

# canonical under all 12 maps followed by any translation (normalize by sorted positions)
def site_from_pos(x,t):
    # solve p=(i+j/2+bx, j/2+bt)
    # j = round(2t); bx,bt close
    jnum=2*t
    if jnum.denominator"'!=1: return None
    j=jnum.numerator
    rem_x=x-j/F(2); rem_t=t-j/F(2)
    for b,(bx,bt) in enumerate(BASIS):
        dx=rem_x-bx; dt=rem_t-bt
        if dt==0 and dx.denominator==1:
            i=dx.numerator
            return (i,j,b)
    return None

def transform_site(s,M):
    x,t=pos(s)
    xp=M[0][0]*x+M[0][1]*t
    tp=M[1][0]*x+M[1][1]*t
    return site_from_pos(xp,tp)

def canonical_point(cl):
    images=[]
    for M in MATS:
        mapped=[]
        ok=True
        for s in cl:
            q=transform_site(s,M)
            if q is None:
                ok=False; break
            mapped.append(q)
        if not ok: continue
        ps=sorted(pos(q) for q in mapped)
        x0,t0=ps[0]
        norm=tuple(sorted((x-x0,t-t0) for x,t in ps))
        images.append(norm)
    return min(images)

classes={}
for cl in raw:
    c=canonical_point(cl)
    classes[c]=classes.get(c,0)+1
print('"'point/space symmetry classes:',len(classes))
for c,n in sorted(classes.items(), key=lambda kv:(str(kv[0]),kv[1])):
    # reconstruct degree info by one representative match
    print('orbit multiplicity in patch', n, 'shape', c)
