  hit=(V[0]<=mu)|(V[1]<=mu)
  for j in range(n):
   vals=[hit[i,j],hit[(i+1)%(2*n),j],hit[i,(j+1)%n],hit[(i+1)%(2*n),(j+1)%n]]
   # contour-adjacent cell if occupancy changes around corners
   crossed[i,j]=any(vals) and not all(vals)
 seen=np.zeros_like(crossed); comps=[]
 for i in range(2*n):
  for j in range(n):
   if not crossed[i,j] or seen[i,j]:continue
   st=[(i,j)];seen[i,j]=1;s=0
   while st:
    x,y=st.pop();s+=1
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
