def contour_graph(mu,n=1000):
 kxs=np.linspace(-np.pi,np.pi,n,endpoint=False); kys=kxs
 V=np.empty((n,n))
 for i,kx in enumerate(kxs):V[i]=E(kx,kys)
 # vertices are crossed horizontal/vertical grid edges; label by (type,i,j)
 vid={}; adj={}
 def add(a,b):
  if a not in vid:vid[a]=len(vid);adj[vid[a]]=[]
  if b not in vid:vid[b]=len(vid);adj[vid[b]]=[]
  adj[vid[a]].append(vid[b]);adj[vid[b]].append(vid[a])
 for i in range(n):
  for j in range(n):
   ip=(i+1)%n;jp=(j+1)%n
   vals=[V[i,j],V[ip,j],V[i,jp],V[ip,jp]]
   s=[v-mu for v in vals]
   # edges: bottom between v0-v1 => ('h',i,j); right v1-v3=>('v',ip,j); top v2-v3=>('h',i,jp); left v0-v2=>('v',i,j)
   edges=[('h',i,j),('v',ip,j),('h',i,jp),('v',i,j)]
   cross=[e for e,(u,v) in zip(edges,[(s[0],s[1]),(s[1],s[3]),(s[2],s[3]),(s[0],s[2])]) if u*v<0]
   if len(cross)==2:add(cross[0],cross[1])
   elif len(cross)==4:
