 # components of graph
 seen=set(); comps=[]
 for v in range(len(vid)):
  if v in seen:continue
  st=[v];seen.add(v);c=0
  while st:
   x=st.pop();c+=1
   for y in adj[x]:
    if y not in seen:seen.add(y);st.append(y)
  comps.append(c)
